async def act(page):
    """
    Attempt to find the post titled "In World First, Chinese Surgeons Save Patient’s Ear With Graft Onto Foot"
    and leave a comment "Excellent write-up!".

    Strategy and use of knowledge-base helpers:
    - create_curated_collection_by_search: preferred helper for driving the site's visible search UI
      and returning search result posts (it directly corresponds to the "search" action). Use it first.
    - extract_post_summaries: fallback helper to scrape visible posts from the homepage when search
      does not locate the target. It reliably returns titles and URLs for visible posts.
    - If helpers fail to find the post, attempt to locate a visible link on the current page via
      page.get_by_role("link", name=..., ).

    All DOM interactions use accessibility-role-centric selectors and locator.count() guards.
    """
    target_title = "In World First, Chinese Surgeons Save Patient’s Ear With Graft Onto Foot"
    comment_text = "Excellent write-up!"

    matched = None

    # 1) Try the visible-search helper first (most direct mapping to searching the site).
    try:
        search_results = await create_curated_collection_by_search(
            page,
            keyword=target_title,
            max_results=0,
            resolve_links=True,
        )
    except Exception:
        search_results = []

    if search_results:
        for r in search_results:
            try:
                title = (r.get("title", "") or "").strip()
            except Exception:
                title = ""
            if title and target_title.lower() in title.lower():
                matched = r
                break

    # 2) Fallback: extract visible posts from the homepage
    if not matched:
        try:
            posts = await extract_post_summaries(page)
        except Exception:
            posts = []
        if posts:
            for p in posts:
                try:
                    title = (p.get("title", "") or "").strip()
                except Exception:
                    title = ""
                if title and target_title.lower() in title.lower():
                    matched = p
                    break

    # 3) Last-resort: try to find a visible link with the exact title on the current page
    if not matched:
        try:
            link_locator = page.get_by_role("link", name=target_title)
            if await link_locator.count() > 0:
                try:
                    href = await link_locator.first.get_attribute("href")
                except Exception:
                    href = None
                if href:
                    matched = {"title": target_title, "url": href}
        except Exception:
            matched = None

    if not matched:
        # Could not locate the post from available strategies; give up gracefully.
        return

    post_url = matched.get("url")
    if not post_url:
        return

    # 4) Navigate to the post page
    try:
        await page.goto(post_url)
    except Exception:
        return

    # Wait for the post page to settle: prefer role="main" then fallback to networkidle
    try:
        main = page.get_by_role("main")
        if await main.count() > 0:
            await main.first.wait_for(timeout=5000)
        else:
            await page.wait_for_load_state("networkidle", timeout=5000)
    except Exception:
        try:
            await page.wait_for_load_state("networkidle", timeout=5000)
        except Exception:
            pass

    # 5) Locate the comment textbox using common accessible labels, then fallback to any textbox
    textbox = None
    candidate_names = [
        "Comment",
        "Leave a comment",
        "Add a comment",
        "Your comment",
        "Write a comment",
        "Reply",
    ]
    for name in candidate_names:
        try:
            locator = page.get_by_role("textbox", name=name)
            if await locator.count() > 0:
                textbox = locator.first
                break
        except Exception:
            continue

    if not textbox:
        try:
            all_textboxes = page.get_by_role("textbox")
            if await all_textboxes.count() > 0:
                textbox = all_textboxes.first
        except Exception:
            textbox = None

    if not textbox:
        # No accessible textbox found; abort.
        return

    # 6) Fill the comment
    try:
        await textbox.fill(comment_text)
    except Exception:
        try:
            await textbox.click()
            await textbox.type(comment_text)
        except Exception:
            return

    # 7) Find the submit button inside the form that contains the textbox
    submit_button = None
    try:
        forms = page.get_by_role("form")
        if await forms.count() > 0:
            form_with_textbox = forms.filter(has=textbox)
            if await form_with_textbox.count() > 0:
                form = form_with_textbox.first
                common_btn_names = [
                    "Post Comment",
                    "Submit Comment",
                    "Submit",
                    "Post",
                    "Comment",
                    "Send",
                ]
                for bn in common_btn_names:
                    try:
                        btn = form.get_by_role("button", name=bn)
                        if await btn.count() > 0:
                            submit_button = btn.first
                            break
                    except Exception:
                        continue
                if not submit_button:
                    try:
                        buttons_in_form = form.get_by_role("button")
                        if await buttons_in_form.count() > 0:
                            submit_button = buttons_in_form.first
                    except Exception:
                        pass
    except Exception:
        submit_button = None

    # 8) Global fallbacks for submit button
    if not submit_button:
        common_btn_names = [
            "Post Comment",
            "Submit Comment",
            "Submit",
            "Post",
            "Comment",
            "Send",
        ]
        for bn in common_btn_names:
            try:
                btn = page.get_by_role("button", name=bn)
                if await btn.count() > 0:
                    submit_button = btn.first
                    break
            except Exception:
                continue

    if not submit_button:
        try:
            all_buttons = page.get_by_role("button")
            if await all_buttons.count() > 0:
                submit_button = all_buttons.first
        except Exception:
            submit_button = None

    if not submit_button:
        # Could not find submit control; abort.
        return

    # 9) Click submit (fall back to pressing Enter in textbox)
    try:
        await submit_button.click()
    except Exception:
        try:
            await textbox.press("Enter")
        except Exception:
            return

    # 10) Wait briefly for submission to process
    try:
        await page.wait_for_load_state("networkidle", timeout=5000)
    except Exception:
        pass

    return

